-- VYRA · Kacper Adamczyk: plan 2026/27 przebudowany na 5 biegów w tygodniu (od czwartku 19.11.2026).
-- Pn: basen, bez biegania · Wt: akcent + siłownia A · Śr: easy + siłownia B · Czw: Run Club (+ szybkość przed) i basen
-- Pt: wolne · Sob: drugi akcent · Nd: long. Daty testów i startów bez zmian.
-- Do zgody lekarza (ciśnienie, kołatanie) akcenty z pierwszych 2 tygodni robisz spokojnie, tyle samo km.
-- Usuwa tylko PRZYSZŁE treningi planu bez zapisanego wykonania. Uruchom w Supabase → SQL Editor. Ponowne uruchomienie nic nie zdubluje.

do $$
declare
  v_ath   uuid;
  v_plan  record;
  v_s     uuid;
  v_ex    uuid;
  v_tpl   record;
  v_del   int;
  v_n     int := 0;
  v_g     int := 0;
  e       jsonb;
  r       record;
  ex      jsonb;
  st      jsonb;
  ex_pos  int;
  st_pos  int;
begin
  select id into v_ath from public.profiles
   where role = 'athlete' and lower(trim(full_name)) = lower('Kacper Adamczyk') order by created_at limit 1;
  if v_ath is null then raise exception 'Nie znaleziono konta zawodnika „Kacper Adamczyk”.'; end if;

  select * into v_plan from public.training_plans where athlete_id = v_ath and name = 'Plan biegowy 2026/27';
  if v_plan.id is null then raise exception 'Nie ma planu „Plan biegowy 2026/27”.'; end if;

  if exists (select 1 from public.training_sessions where plan_id = v_plan.id and notes like 'Plan na 5 dni%') then
    raise notice 'Plan na 5 dni już jest, nic nie zmieniono.';
    return;
  end if;

  perform set_config('vyra.bulk', 'on', true);

  -- 1) Przyszłe treningi starego układu (bieganie i siłownia), bez zapisanego wykonania.
  delete from public.training_sessions s
   where s.plan_id = v_plan.id and s.scheduled_date >= date '2026-11-19' and s.kind in ('running', 'strength')
     and s.status = 'planned'
     and not exists (select 1 from public.workout_executions x where x.session_id = s.id);
  get diagnostics v_del = row_count;

  -- 2) Nowy układ: 5 biegów w tygodniu.
  for e in select * from jsonb_array_elements('[{"date": "2026-11-19", "cat": "easy", "km": 6, "title": "Run Club luźno", "instr": "1 km truchtu + Run Club 18:00 (ok. 5 km w tempie rozmowy). Bez przebieżek.", "notes": "Plan na 5 dni · Tydzień przejściowy: odpoczynek po zmęczeniu, bez akcentów."}, {"date": "2026-11-21", "cat": "easy", "km": 9, "title": "Easy 9 km + przebieżki", "instr": "9 km easy + 6 przebieżek 100 m. Tylko jeśli gotowość na zegarku jest co najmniej średnia; inaczej 6 km.", "notes": "Plan na 5 dni · Tydzień przejściowy: odpoczynek po zmęczeniu, bez akcentów."}, {"date": "2026-11-22", "cat": "easy", "km": 8, "title": "Easy 8 km", "instr": "8 km bardzo spokojnie albo wolne, jeśli dalej czujesz się zmęczony.", "notes": "Plan na 5 dni · Tydzień przejściowy: odpoczynek po zmęczeniu, bez akcentów."}, {"date": "2026-11-24", "cat": "easy", "km": 10, "title": "Easy 10 km + przebieżki · siłownia A", "instr": "10 km easy + 6×20 s żwawo / 1 min trucht · Siłownia A (lekko, 2×10)", "notes": "Plan na 5 dni · Tydzień 1 planu na 5 dni. Powrót: wszystko spokojnie, przebieżki zostają. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-11-25", "cat": "easy", "km": 10, "title": "Easy 10 km · siłownia B", "instr": "10 km easy · Siłownia B (lekko, bez skoków)", "notes": "Plan na 5 dni · Tydzień 1 planu na 5 dni. Powrót: wszystko spokojnie, przebieżki zostają. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-11-26", "cat": "easy", "km": 8, "title": "Run Club + rozbieganie", "instr": "3 km easy przed zbiórką + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 1 planu na 5 dni. Powrót: wszystko spokojnie, przebieżki zostają. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-11-28", "cat": "fartlek", "km": 10, "title": "10 km, w środku 6×2 min żwawo", "instr": "3 km + 6×2 min RPE 6 (próg: tętno 165-172, ok. 3:55) / 2 min trucht + 3 km. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie.", "notes": "Plan na 5 dni · Tydzień 1 planu na 5 dni. Powrót: wszystko spokojnie, przebieżki zostają. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-11-29", "cat": "long", "km": 14, "title": "Długi bieg 14 km", "instr": "14 km easy, tempo rozmowy", "notes": "Plan na 5 dni · Tydzień 1 planu na 5 dni. Powrót: wszystko spokojnie, przebieżki zostają. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-01", "cat": "intervals", "km": 11, "title": "5×1000 m progowo · siłownia A", "instr": "3 km + 5×1000 m (próg: tętno 165-172, ok. 3:55), 1 min trucht + 2 km · Siłownia A (2×10). Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie.", "notes": "Plan na 5 dni · Tydzień 2. Pierwsze odcinki progowe, objętość nadal niska. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-02", "cat": "easy", "km": 11, "title": "Easy 11 km · siłownia B", "instr": "11 km easy + 6 przebieżek · Siłownia B (lekko)", "notes": "Plan na 5 dni · Tydzień 2. Pierwsze odcinki progowe, objętość nadal niska. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-03", "cat": "easy", "km": 8, "title": "Run Club + przebieżki", "instr": "3 km easy + 6×100 m swobodnie szybko + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 2. Pierwsze odcinki progowe, objętość nadal niska. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-05", "cat": "fartlek", "km": 10, "title": "Fartlek mieszany", "instr": "3 km + 8×(1 min w 3:40 + 20 s w 3:10), 90 s lekko między + 3 km. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie.", "notes": "Plan na 5 dni · Tydzień 2. Pierwsze odcinki progowe, objętość nadal niska. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-06", "cat": "long", "km": 16, "title": "Długi bieg 16 km", "instr": "16 km easy", "notes": "Plan na 5 dni · Tydzień 2. Pierwsze odcinki progowe, objętość nadal niska. Akcent tylko po zgodzie lekarza (ciśnienie, kołatanie). Bez zgody: tyle samo km spokojnie."}, {"date": "2026-12-08", "cat": "fartlek", "km": 12, "title": "Fartlek progowy · siłownia A", "instr": "3 km + 4×(5 min próg: tętno 165-172 + 1 min w 3:35), 1 min lekko między + 2 km · Siłownia A (3×8)", "notes": "Plan na 5 dni · Tydzień 3. Dłuższe odcinki progowe."}, {"date": "2026-12-09", "cat": "easy", "km": 12, "title": "Easy 12 km · siłownia B", "instr": "12 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 3. Dłuższe odcinki progowe."}, {"date": "2026-12-10", "cat": "easy", "km": 9, "title": "Run Club + podbiegi", "instr": "3 km easy + 8×10 s pod górę (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 3. Dłuższe odcinki progowe."}, {"date": "2026-12-12", "cat": "fartlek", "km": 11, "title": "Fartlek mieszany", "instr": "3 km + 6×(2 min w 3:40 + 30 s w 3:05), 1 min lekko między + 2 km", "notes": "Plan na 5 dni · Tydzień 3. Dłuższe odcinki progowe."}, {"date": "2026-12-13", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Plan na 5 dni · Tydzień 3. Dłuższe odcinki progowe."}, {"date": "2026-12-15", "cat": "threshold", "km": 14, "title": "3×3 km progowo · siłownia A", "instr": "3 km + 3×3 km (próg: tętno 165-172), 1 min trucht + 2 km · Siłownia A (3×6)", "notes": "Plan na 5 dni · Tydzień 4. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-16", "cat": "easy", "km": 12, "title": "Easy 12 km · siłownia B", "instr": "12 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 4. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-17", "cat": "easy", "km": 9, "title": "Run Club + flying", "instr": "3 km easy + 4×60 m flying szybko (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 4. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-19", "cat": "test", "km": 10, "title": "Test 3 km", "instr": "3 km rozgrzewki, 4 przebieżki, 3 km maksymalnie równo (bieżnia), 2 km schłodzenia. Wynik wpisz do aplikacji.", "notes": "Plan na 5 dni · Tydzień 4. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-20", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Plan na 5 dni · Tydzień 4. Test 3 km w sobotę: z wyniku przeliczamy tempa."}, {"date": "2026-12-22", "cat": "intervals", "km": 15, "title": "5×2000 m progowo · siłownia A", "instr": "3 km + 5×2000 m (próg: tętno 165-172), 1 min trucht + 2 km · Siłownia A (ciężko, 4×5)", "notes": "Plan na 5 dni · Tydzień 5. Najmocniejszy tydzień przed świętami."}, {"date": "2026-12-23", "cat": "easy", "km": 13, "title": "Easy 13 km · siłownia B", "instr": "13 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 5. Najmocniejszy tydzień przed świętami."}, {"date": "2026-12-24", "cat": "intervals", "km": 10, "title": "Szybkość + Run Club", "instr": "3 km + plyo lekkie + 6×150 m w 23-24 s (pełna przerwa) + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 5. Najmocniejszy tydzień przed świętami."}, {"date": "2026-12-26", "cat": "fartlek", "km": 11, "title": "Fartlek na pagórkach", "instr": "3 km + 6×(2 min w 3:30 + 30 s w 3:05), 90 s lekko między + 2 km", "notes": "Plan na 5 dni · Tydzień 5. Najmocniejszy tydzień przed świętami."}, {"date": "2026-12-27", "cat": "long", "km": 20, "title": "Długi bieg 20 km", "instr": "20 km easy", "notes": "Plan na 5 dni · Tydzień 5. Najmocniejszy tydzień przed świętami."}, {"date": "2026-12-29", "cat": "i