 "title": "Drabina", "instr": "3 km + 2×(200-400-600-400-200 m w 3:10/km), 200 m lekko, 4 min między seriami + 2 km", "notes": "Plan na 5 dni · Tydzień 7. Dłuższe powtórzenia progowe i pierwsze 200-tki."}, {"date": "2027-01-10", "cat": "long", "km": 20, "title": "Długi bieg 20 km", "instr": "20 km easy", "notes": "Plan na 5 dni · Tydzień 7. Dłuższe powtórzenia progowe i pierwsze 200-tki."}, {"date": "2027-01-12", "cat": "intervals", "km": 15, "title": "5×2000 m progowo · siłownia A", "instr": "3 km + 5×2000 m (próg: tętno 165-172, ok. 3:50-3:53), 1 min trucht + 2 km · Siłownia A (ciężko, 4×5)", "notes": "Plan na 5 dni · Tydzień 8."}, {"date": "2027-01-13", "cat": "easy", "km": 13, "title": "Easy 13 km · siłownia B", "instr": "13 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 8."}, {"date": "2027-01-14", "cat": "intervals", "km": 10, "title": "200-tki + Run Club", "instr": "3 km + plyo + 6×200 m w 34 s + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 8."}, {"date": "2027-01-16", "cat": "fartlek", "km": 12, "title": "Fartlek 3 temp", "instr": "3 km + 4×(3 min w 3:30 + 1 min w 3:10 + 30 s w 2:55), 2 min lekko między + 2 km", "notes": "Plan na 5 dni · Tydzień 8."}, {"date": "2027-01-17", "cat": "long", "km": 22, "title": "Długi bieg 22 km", "instr": "22 km easy", "notes": "Plan na 5 dni · Tydzień 8."}, {"date": "2027-01-19", "cat": "fartlek", "km": 13, "title": "Fartlek progowy · siłownia A", "instr": "3 km + 4×(5 min próg: tętno 165-172 + 1 min w 3:30 + 1 min w 3:22), 1 min lekko + 2 km · Siłownia A (4×4-5)", "notes": "Plan na 5 dni · Tydzień 9. Szczyt bazy i pierwsza prędkość 1000 m (300 m w 51-52 s)."}, {"date": "2027-01-20", "cat": "easy", "km": 13, "title": "Easy 13 km · siłownia B", "instr": "13 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 9. Szczyt bazy i pierwsza prędkość 1000 m (300 m w 51-52 s)."}, {"date": "2027-01-21", "cat": "intervals", "km": 10, "title": "300-tki + Run Club", "instr": "3 km + plyo + 6×