"km": 12, "title": "Easy 12 km", "instr": "12 km easy", "notes": "Plan na 5 dni · Tydzień 24. Tydzień finału XC (czwartek). Jeśli data finału jest inna, przesuń dni względem niej."}, {"date": "2027-05-11", "cat": "intervals", "km": 11, "title": "5×1000 m progowo · siłownia A", "instr": "3 km + 5×1000 m (próg: tętno 165-172), 1 min trucht + 2 km · Siłownia A (3×6)", "notes": "Plan na 5 dni · Tydzień 25. Powrót do progu po przełaju, siłownia znowu 2×."}, {"date": "2027-05-12", "cat": "easy", "km": 12, "title": "Easy 12 km · siłownia B", "instr": "12 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 25. Powrót do progu po przełaju, siłownia znowu 2×."}, {"date": "2027-05-13", "cat": "intervals", "km": 9, "title": "150-tki + Run Club", "instr": "3 km + plyo + 6×150 m w 23-24 s + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 25. Powrót do progu po przełaju, siłownia znowu 2×."}, {"date": "2027-05-15", "cat": "fartlek", "km": 10, "title": "Teren 1 min / 15 s", "instr": "10 km w terenie, w środku 8×(1 min w 3:30 + 15 s w 2:50), 90 s lekko, RPE 7", "notes": "Plan na 5 dni · Tydzień 25. Powrót do progu po przełaju, siłownia znowu 2×."}, {"date": "2027-05-16", "cat": "long", "km": 18, "title": "Długi bieg 18 km", "instr": "18 km easy", "notes": "Plan na 5 dni · Tydzień 25. Powrót do progu po przełaju, siłownia znowu 2×."}, {"date": "2027-05-18", "cat": "intervals", "km": 15, "title": "5×2000 m progowo · siłownia A", "instr": "3 km + 5×2000 m (próg: tętno 165-172), 1 min trucht + 2 km · Siłownia A (3×5)", "notes": "Plan na 5 dni · Tydzień 26. Budowa pod 10 km i półmaraton."}, {"date": "2027-05-19", "cat": "easy", "km": 12, "title": "Easy 12 km · siłownia B", "instr": "12 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 26. Budowa pod 10 km i półmaraton."}, {"date": "2027-05-20", "cat": "intervals", "km": 9, "title": "200-tki + Run Club", "instr": "3 km + plyo + 6×200 m w 34 s + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 26. Budowa pod 10 km i półmaraton."}, {"date": "2027-05-22", "cat": "fartlek", "km": 10, "title": "Teren 90 s / 30 s", "instr": "10 km w terenie, w środku 6×(90 s w 3:25 + 30 s w 3:00), 90 s lekko, RPE 7", "notes": "Plan na 5 dni · Tydzień 26. Budowa pod 10 km i półmaraton."}, {"date": "2027-05-23", "cat": "progression", "km": 20, "title": "Długi 20 km z końcówką", "instr": "20 km, ostatnie 6 km w 4:05", "notes": "Plan na 5 dni · Tydzień 26. Budowa pod 10 km i półmaraton."}, {"date": "2027-05-25", "cat": "threshold", "km": 14, "title": "3×3 km progowo · siłownia A", "instr": "3 km + 3×3 km (próg: tętno 165-172, ok. 3:48-3:50), 1 min trucht + 2 km · Siłownia A (3×5)", "notes": "Plan na 5 dni · Tydzień 27. Szczyt maja."}, {"date": "2027-05-26", "cat": "easy", "km": 13, "title": "Easy 13 km · siłownia B", "instr": "13 km easy · Siłownia B", "notes": "Plan na 5 dni · Tydzień 27. Szczyt maja."}, {"date": "2027-05-27", "cat": "intervals", "km": 9, "title": "200-tki + Run Club", "instr": "3 km + plyo + 6×200 m w 33-34 s + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 27. Szczyt maja."}, {"date": "2027-05-29", "cat": "intervals", "km": 10, "title": "Szybkość 30 s", "instr": "10 km easy, w środku 8×(30 s w 3:05 / 90 s lekko)", "notes": "Plan na 5 dni · Tydzień 27. Szczyt maja."}, {"date": "2027-05-30", "cat": "progression", "km": 22, "title": "Długi 22 km z końcówką", "instr": "22 km, ostatnie 8 km w 4:05", "notes": "Plan na 5 dni · Tydzień 27. Szczyt maja."}, {"date": "2027-06-01", "cat": "intervals", "km": 11, "title": "5×1000 m progowo", "instr": "3 km + 5×1000 m (próg: tętno 165-172, ok. 3:48), 1 min trucht + 2 km · Siłownia A (lekko)", "notes": "Plan na 5 dni · Tydzień 28. Lżejszy + 10 km kontrolny w niedzielę (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}, {"date": "2027-06-02", "cat": "easy", "km": 10, "title": "Easy 10 km", "instr": "10 km easy · Siłownia B (lekko)", "notes": "Plan na 5 dni · Tydzień 28. Lżejszy + 10 km kontrolny w niedzielę (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}, {"date": "2027-06-03", "cat": "intervals", "km": 8, "title": "150-tki + Run Club", "instr": "2 km + 6×150 m szybko + Run Club 18:00 (ok. 5 km w tempie rozmowy)", "notes": "Plan na 5 dni · Tydzień 28. Lżejszy + 10 km kontrolny w niedzielę (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}, {"date": "2027-06-05", "cat": "easy", "km": 4, "title": "20 min + przebieżki", "instr": "20 min easy + 4 przebieżki", "notes": "Plan na 5 dni · Tydzień 28. Lżejszy + 10 km kontrolny w niedzielę (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}, {"date": "2027-06-06", "cat": "test", "km": 14, "title": "10 km kontrolny", "instr": "2 km rozgrzewki, 10 km równo, 2 km schłodzenia", "notes": "Plan na 5 dni · Tydzień 28. Lżejszy + 10 km kontrolny w niedzielę (cel ok. 36:30). Wynik decyduje o terminie półmaratonu."}]'::jsonb) loop
    insert into public.training_sessions (coach_id, athlete_id, plan_id, kind, category, title, scheduled_date, instructions, notes)
    values (v_plan.coach_id, v_ath, v_plan.id, 'running', e->>'cat', e->>'title', (e->>'date')::date, e->>'instr', e->>'notes')
    returning id into v_s;
    insert into public.running_workouts (session_id, structure, planned_distance_m)
    values (v_s,
            case e->>'cat' when 'fartlek' then 'fartlek' when 'progression' then 'progression'
                           when 'intervals' then 'intervals' when 'threshold' then 'intervals' when 'hills' then 'intervals'
                           when 'race_pace' then 'intervals' else 'continuous' end,
            (e->>'km')::int * 1000);
    v_n := v_n + 1;
  end loop;

  -- 3) Siłownia A (wtorek) i B (środa) jako osobne treningi z szablonów.
  for r in
    select s.scheduled_date, (regexp_match(s.instructions, 'Siłownia ([AB])(?:\s*\(([^)]*)\))?')) as m
      from public.training_sessions s
     where s.plan_id = v_plan.id and s.kind = 'running' and s.scheduled_date >= date '2026-11-19'
       and s.instructions ~ 'Siłownia [AB]'
     order by s.scheduled_date
  loop
    select * into v_tpl from public.training_templates
     where name = case r.m[1] when 'A' then 'Siłownia A: nogi i siła' else 'Siłownia B: plyo i stabilizacja' end
     order by created_at limit 1;
    continue when v_tpl.id is null;
    continue when exists (select 1 from public.training_sessions
                           where athlete_id = v_ath and scheduled_date = r.scheduled_date and kind = 'strength' and template_id = v_tpl.id);
    insert into public.training_sessions (coach_id, athlete_id, plan_id, template_id, kind, category, title, scheduled_date,
                                          goal, instructions, notes, planned_duration_s)
    values (v_plan.coach_id, v_ath, v_plan.id, v_tpl.id, 'strength', v_tpl.category,
            v_tpl.payload->>'title' || coalesce(' (' || r.m[2] || ')', ''), r.scheduled_date,
            coalesce('Wskazówka z planu: ' || r.m[2] || '. ', '') || coalesce(v_tpl.payload->>'goal', ''),
            v_tpl.payload->>'instructions', 'Plan na 5 dni · Po bieganiu tego dnia (min. 3 godziny po akcencie).',
            nullif(v_tpl.payload->>'planned_duration_s', '')::int)
    returning id into v_s;
    for ex, ex_pos in select x, o::int from jsonb_array_elements(v_tpl.payload->'exercises') with ordinality as t(x, o) loop
      insert into public.strength_exercises (session_id, position, name, description, muscle_group, rest_s, tempo, notes)
      values (v_s, ex_pos, ex->>'name', ex->>'description', ex->>'muscle_group', nullif(ex->>'rest_s', '')::int, ex->>'tempo', ex->>'notes')
      returning id into v_ex;
      for st, st_pos in select x, o::int from jsonb_array_elements(ex->'sets') with ordinality as t(x, o) loop
        insert into public.strength_sets (exercise_id, position, planned_reps, planned_load_kg, planned_duration_s, planned_rpe, planned_rir)
        values (v_ex, st_pos, nullif(st->>'planned_reps', '')::int, nullif(st->>'planned_load_kg', '')::numeric,
                nullif(st->>'planned_duration_s', '')::int, nullif(st->>'planned_rpe', '')::numeric, nullif(st->>'planned_rir', '')::int);
      end loop;
    end loop;
    v_g := v_g + 1;
  end loop;

  update public.training_plans
     set description = 'Od 19.11.2026: 5 biegów w tygodniu. Pn basen, Wt akcent + siłownia A, Śr easy + siłownia B, Czw Run Club + basen, Pt wolne, Sob akcent, Nd long. Easy = tempo rozmowy, tętno do ok. 155. Próg prowadzony tętnem 165-172.'
   where id = v_plan.id;

  perform set_config('vyra.bulk', '', true);
  perform public.notify(v_ath, 'session_assigned', 'Plan przebudowany: 5 biegów w tygodniu',
    v_n || ' biegów i ' || v_g || ' × siłownia · od 19.11', '/athlete/calendar', null);
  raise notice 'Usunięto % starych, dodano % biegów i % treningów siłowych.', v_del, v_n, v_g;
end $$;
